// ============================================================================
// UCIe_apb: APB4 register wrapper around UCIe_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/UCIe.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/UCIe.md
// ============================================================================
module UCIe_apb #(
  parameter int RB = 8,
  // replay buffer entries, power of 2, at most 8
  parameter int TO = 32
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic lt_valid,
  output logic [89:0] lt_flit,
  input logic lr_valid,
  input logic [89:0] lr_flit
);
  localparam logic [31:0] ID_VALUE = 32'h55430200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_tx_valid;
  logic [63:0]   c_tx_data;
  logic          c_tx_ready;
  logic          c_rx_valid;
  logic [63:0]   c_rx_data;
  logic [3:0]    c_tx_pend;
  logic          c_ev_crc;
  logic          c_ev_replay;
  UCIe_top #(.RB(RB), .TO(TO)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .tx_valid(c_tx_valid),
    .tx_data(c_tx_data),
    .tx_ready(c_tx_ready),
    .rx_valid(c_rx_valid),
    .rx_data(c_rx_data),
    .lt_valid(lt_valid),
    .lt_flit(lt_flit),
    .lr_valid(lr_valid),
    .lr_flit(lr_flit),
    .tx_pend(c_tx_pend),
    .ev_crc(c_ev_crc),
    .ev_replay(c_ev_replay)
  );

  // ---------------- registers ----------------
  logic [5:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] h_TX0;   // 12'h014 TX0 holding register
  logic [31:0] h_TX1;   // 12'h018 TX1 holding register
  logic [31:0] h_RX0;   // 12'h01C RX0 holding register
  logic [31:0] h_RX1;   // 12'h020 RX1 holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      h_TX0 <= '0;
      h_TX1 <= '0;
      h_RX0 <= '0;
      h_RX1 <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[5:0] & wmask[5:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[5:0]) | (PWDATA[5:0] & wmask[5:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5] && !full_TX) h_TX0 <= (h_TX0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6] && !full_TX) h_TX1 <= (h_TX1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[8]))) begin
        h_RX0[31:0] <= c_rx_data[31:0];
        h_RX1[31:0] <= c_rx_data[63:32];
        avail_RX <= 1'b1;
      end else if (rd && hit[8]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_tx_data[31:0] = h_TX0[31:0];
  assign c_tx_data[63:32] = h_TX1[31:0];
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_ev_crc;
    irq_set[1] = c_ev_replay;
    irq_set[2] = full_TX & c_tx_ready;
    irq_set[3] = wr & (hit[5] | hit[6]) & full_TX;
    irq_set[4] = c_rx_valid & (~avail_RX | (rd & hit[8]));
    irq_set[5] = c_rx_valid & avail_RX & ~(rd & hit[8]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(h_TX0);
      10'd6: rdata = 32'(h_TX1);
      10'd7: rdata = 32'(h_RX0);
      10'd8: rdata = 32'(h_RX1);
      10'd9: rdata = 32'({c_tx_pend});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
